UPDATE lessons SET title='Year 4, Week 30, Lesson 1: Elapsed time', data=json_patch(data,'{"child_mission":"Elapsed time is the duration from a start time to an end time; jump hours then minutes on a number line or clock.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nHow much time from 2:40 pm to 4:15 pm?\n\nFEEDBACK\n1 hour 35 minutes.\n\nWATCH FOR\nSubtracting digital times as if they were base-100 decimals (e.g. 4.15−2.40) fails when minutes borrow.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nFind elapsed time for fourteen start–end pairs. Show hour then minute jumps for eight.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"Elapsed time is the duration from a start time to an end time; jump hours then minutes on a number line or clock.","lesson_number":1,"lesson_role":"Concept","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-NSM-02"],"parent_notes":"Parent: Marking guidance for the independent task: Find elapsed time for fourteen start–end pairs. Show hour then minute jumps for eight. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new numbers solved with visible working for elapsed; key places/values named. Do not award marks for retyping the model.\n\nParent: Written model 2: Sample misconception: Subtracting digital times as if they were base-100 decimals (e.g.. Correction uses 1 hour 35 minutes.. Why: restores accurate elapsed.\n\nParent: Likely misconception: Subtracting digital times as if they were base-100 decimals (e.g. 4.15−2.40) fails when minutes borrow. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Solve one fresh problem that uses elapsed with different numbers from the worked model. Show working and name the places or values that matter.\n\nParent: Short-answer focus 2: Describe one likely mistake with elapsed, show corrected working, and say why the correction works.\n\nParent: Marking notes: Accept any mathematically valid solution that uses new numbers, shows working for elapsed, and names places/values. Reject copied model numbers. / Accept a named misconception about elapsed, corrected working, and a method reason. Reject vague “I was wrong” with no repair..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":1,"explanation":"This matches the taught method for elapsed. The other choices miss a key step or use a common mistake.","options":["A method that skips the key step taught in this lesson","1 hour 35 minutes","Subtracting digital times as if they were base-100 decimals (e.g","A claim that names no evidence from the lesson material"],"question":"How much time from 2:40 pm to 4:15 pm?","type":"multiple_choice"},{"correct_index":2,"explanation":"This is the misconception to avoid for elapsed; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["1 hour 35 minutes","Careful use of duration and explain why it matters with clear evidence","Subtracting digital times as if they were base-100 decimals (e.g","Elapsed time is the duration from a start time to an end time"],"question":"Which statement is a common mistake when working with elapsed?","type":"multiple_choice"},{"corr